        CfUtils.SetTopCommonCb(function ()
            --- 比较当前界面的展示配置 与 原始的展示配置
            local isChange = self:CheckDisplayCatIsChange()
            if isChange then
                GameUtils.SecondConfirm(localize("本次设置有更改未保存,是否要退出猫咪列表"), function ()
                    UIModule.BackDialog()
                end)
            else
                UIModule.BackDialog()
            end
        end)
    else
        CfUtils.ResetNavigatorCustomBackAction()
    end
end

