function CatHouseDisplaySettingDialog:InitData()
    -----------------------------
    ---配表相关
    --- 喵喵屋主界面可显示猫咪数量
    local maxMainShowNun = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.MaxMainShowNun).num)

    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    
    self.catHouseHomeDojo = catHouseHomeDojo
    self.localCatShowNum  = catHouseHomeDojo.localCatShowNum
    self.maxMainShowNun  = maxMainShowNun
    self.viewType        = ViewType.Display
end

function CatHouseDisplaySettingDialog:InitCardList()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catHouseHomeDojo = self.catHouseHomeDojo

    local displayIdMap = {}
    local catList = {}
    for i, v in ipairs(catHouseHomeDojo.catList) do
        if checkTable(component:GetCDDataById(v.id))[ConstantsCatHouse.CatStatus.Hatching] == nil then
            if checkNumber(v.isShow) == 1 then
                displayIdMap[checkNumber(v.id)] = i
            end
            table.insert(catList, v)
        end
    end

    self.catList            = catList
    self.displayIdMap       = displayIdMap
    self.originDisplayIdMap = clone(displayIdMap)

end


