function CatHouseDisplaySettingDialog:FreshUI()
    self:FreshDisplayNum()
    self:FreshListUI()
    
end

function CatHouseDisplaySettingDialog:FreshDisplayNum()
    self.Text2.text = string.format("%s/%s", self.localCatShowNum, self.maxMainShowNun)
end

function CatHouseDisplaySettingDialog:FreshListUI()
    local len  = #self.catList
    local List = self.CatDisplayList
    if not List.mLoopListView.IsListViewInit then
        List:InitListView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseDisplaySettingDialog:OnGetItemByIndex(cell, index)
    if index < 0 then
        return nil
    end

    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then
        return nil
    end
    
    local position = index + 1
    local catData  = self.catList[position]
    nodeEnv:SetCallback(function ()
        self:OnClickCatNodeAction(catData, position)
    end)
    nodeEnv:FreshCommonUI(catData)
    nodeEnv:FreshStatusDisplayShowState(checkNumber(catData.isShow))

    return cell

end

function CatHouseDisplaySettingDialog:FreshStatusDisplayShowState(index, isShow)
    local node = self.CatDisplayList:GetShownItemByItemIndex(index - 1)
    if isNull(node) then return end
    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(node, CellEnvPath)
    if isNull(nodeEnv) then return end
    nodeEnv:FreshStatusDisplayShowState(isShow)
end

function CatHouseDisplaySettingDialog:CheckDisplayCatIsChange()
    local originCount        = self.catHouseHomeDojo.localCatShowNum
    local curCount           = self.localCatShowNum
    if originCount ~= curCount then
        return true
    end

    local displayIdMap       = self.displayIdMap      
    local originDisplayIdMap = self.originDisplayIdMap
    for playerCatId, v in pairs(originDisplayIdMap) do
        if displayIdMap[playerCatId] then
            originCount = originCount - 1
        end
    end

    return originCount ~= 0
end

