function CatHouseDisplaySettingDialog:OnClickSaveSettingsAction()
    if not self:CheckDisplayCatIsChange() then
        return
    end

    --- 服务端接受的是变化过的Id
    local changeIdList       = {}
    local displayIdMap       = self.displayIdMap      
    local originDisplayIdMap = self.originDisplayIdMap
    for playerCatId, v in pairs(originDisplayIdMap) do
        --- 如果当前展示数据没有该Id 则插入
        if not displayIdMap[playerCatId] then
            --- 此Id数据 isShow 1 -> 0
            table.insert(changeIdList, playerCatId)
        end
    end
    local displayIdList = {}
    for playerCatId, v in pairs(displayIdMap) do
        --- 如果原始展示数据没有该Id 则插入
        if not originDisplayIdMap[playerCatId] then
            --- 此Id数据 isShow 0 -> 1
            table.insert(changeIdList, playerCatId)
        end
        table.insert(displayIdList, playerCatId)
    end

    -- print("changeIdList--->>>", table.toString(changeIdList))
    GameUtils.Request(Interfaces.CatHouseSetShowCat, {
        playerCatIds = next(displayIdList) == nil and "" or table.concat(displayIdList, ",")
    }, function(req, response)
        ------------------------
        --- 1. 处理数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        
        ---@type CatHouseHomeDojo
        local catHouseHomeDojo = component:GetCatHouseHomeDojo()
        catHouseHomeDojo.localCatShowNum = table.count(displayIdMap)

        for i, playerCatId in ipairs(changeIdList) do
            local catData = component:GetCatDataById(playerCatId)
            local isShow  = checkNumber(catData.isShow)
            --- 交换改变数据的状态
            catData.isShow = isShow == 1 and 0 or 1
        end

        ------------------------
        ---2. 回到上一级界面
        UIModule.BackDialog()

        ------------------------
        ---3. Toast
        GameUtils.Toast(localize("已设置"))
    end)
end

function CatHouseDisplaySettingDialog:OnClickCatNodeAction(catData, position)
    local id              = checkNumber(catData.id)
    local oldDisplauIndex = self.displayIdMap[id]
    local isInShow        = (oldDisplauIndex ~= nil)
    if not isInShow and table.count(self.displayIdMap) >= self.maxMainShowNun then
        GameUtils.Toast(localize("猫屋内展示猫咪已达上限"))
        return
    end

    local displayIndex    = isInShow and oldDisplauIndex or position
    local displayRes      = isInShow and 0 or 1
    self:FreshStatusDisplayShowState(displayIndex, displayRes)

    self.localCatShowNum = self.localCatShowNum + (isInShow and -1 or 1)

    self.displayIdMap[id] = (oldDisplauIndex == nil) and position or nil

    self:FreshDisplayNum()


end

